// testAccCheckEfloErAttachmentDestroy queries GetErAttachment directly after Terraform
// destroyed the attachment and requires the API to report it as absent. The request and
// the not-found decision live in the test so the check does not reuse the resource's own
// read path.
func testAccCheckEfloErAttachmentDestroy(s *terraform.State) error {
	for _, rs := range s.RootModule().Resources {
		if rs.Type != "alicloud_eflo_er_attachment" {
			continue
		}
		parts := strings.Split(rs.Primary.ID, ":")
		if len(parts) != 2 {
			return fmt.Errorf("unexpected er attachment id %q", rs.Primary.ID)
		}
		client := acctest.Provider.Meta().(*connectivity.AliyunClient)
		request := map[string]interface{}{
			"RegionId":       client.RegionId,
			"ErId":           parts[0],
			"ErAttachmentId": parts[1],
		}
		response, err := client.RpcPost("eflo", "2022-05-30", "GetErAttachment", nil, request, true)
		if err != nil {
			if isErAttachmentNotFoundCode(err) {
				continue
			}
			return fmt.Errorf("describing er attachment %s failed: %s", rs.Primary.ID, err)
		}
		// A successful answer means the object is still there; absence is only
		// signalled by the contract's not-found code handled above.
		return fmt.Errorf("er attachment %s still exists after destroy: %v", rs.Primary.ID, response)
	}
	return nil
}

// testAccCheckEfloErAttachmentRegion compares the region resolved by the regions data
// source with the region the acceptance precheck settled on. The precheck may switch
// regions at runtime, so the comparison happens when the step is checked.
func testAccCheckEfloErAttachmentRegion(dataSource string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		if acctest.DefaultRegionToTest == "" {
			return fmt.Errorf("acceptance region was not resolved before checking %s", dataSource)
		}
		return resource.TestCheckResourceAttr(dataSource, "regions.0.id", acctest.DefaultRegionToTest)(s)
	}
}

// isErAttachmentNotFoundCode requires the exact contract code for absence so the
// destroy check never reports a deleted attachment on an unrelated API failure.
func isErAttachmentNotFoundCode(err error) bool {
	for err != nil {
		if sdkError, ok := err.(*tea.SDKError); ok {
			return sdkError.Code != nil && *sdkError.Code == "1003"
		}
		if wrapped, ok := err.(interface{ Unwrap() error }); ok {
			err = wrapped.Unwrap()
		} else {
			return false
		}
	}
	return false
}

